# Generated by Yandex Photo & Video Downloader. Run from the download folder.
$ErrorActionPreference = 'Stop'
$data = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'yandex-downloads.json') -Raw -Encoding UTF8 | ConvertFrom-Json
if ($data.format -ne 'yandex-photo-video-downloader' -or $data.version -ne 1) { throw 'Unknown metadata format' }
$failed = 0
foreach ($entry in $data.files) {
    try {
        $name = $entry.savedName
        if ($name -isnot [string] -or $name -in @('', '.', '..') -or $name -match '[\\/:]' -or [IO.Path]::GetFileName($name) -cne $name) { throw 'Invalid file name' }
        $file = Get-Item -LiteralPath (Join-Path $PSScriptRoot $name) -Force
        if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $file.Length -ne $entry.bytes) { throw 'File is missing, changed or not a regular file' }
        $created = [DateTimeOffset]::ParseExact($entry.createdAt, "yyyy-MM-dd'T'HH:mm:ss.fff'Z'", [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::AssumeUniversal)
        $modified = [DateTimeOffset]::ParseExact($entry.modifiedAt, "yyyy-MM-dd'T'HH:mm:ss.fff'Z'", [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::AssumeUniversal)
        $file.CreationTimeUtc = $created.UtcDateTime
        $file.LastWriteTimeUtc = $modified.UtcDateTime
        $file.Refresh()
        if ($file.CreationTimeUtc -ne $created.UtcDateTime -or $file.LastWriteTimeUtc -ne $modified.UtcDateTime) { throw 'File system did not preserve the requested dates' }
        Write-Output "OK: $name"
    } catch {
        $failed++
        Write-Warning "$($entry.savedName): $($_.Exception.Message)"
    }
}
if ($failed) { exit 1 }
